INSERT INTO formulaires_candidats (FC_MessageId, FC_Date, FC_From, FC_Subject, FC_Prenom, FC_Nom, FC_Tel, FC_Email, FC_Ville, FC_Linkedin, FC_Pourquoi, FC_Delai, FC_Corps, FC_Statut) SELECT '<MI3P195MB3300A3F95911A153D3D04733CC682@MI3P195MB3300.EURP195.PROD.OUTLOOK.COM>', '2026-11-04 05:29:46', 'Georges-Louis DUQUESNE <glduquesne@hotmail.com>', 'Nouveau formulaire de recrutement via réseaux sociaux', 'Tara', 'Maurel', '+33637803659', 'taramaurel.pro@gmail.com', 'Paris', '', 'Après plusieurs années à explorer le marché parisien, visiter et repérer le potentiel des biens, j''ai déniché l''appartement familial que nous achetons aujourd''hui. Cette recherche a confirmé mon envie, présente depuis longtemps, d''en faire une activité professionnelle. L''arrivée de mon premier enfant marque le moment de concrétiser ce projet : mettre ma ténacité, ma connaissance de Paris et mon plaisir de chercher au service des clients de Perle Rare.', '00:12:17', 'Votre prénom ? Tara\n\nVotre nom ? Maurel\n\nVotre numtel ?  +33637803659\n\nVotre email ? taramaurel.pro@gmail.com\n\nOù habitez-vous ? Paris\n\nLien linkedIn : \n\nPourquoi rejoindre PR : Après plusieurs années à explorer le marché parisien, visiter et repérer le potentiel des biens, j''ai déniché l''appartement familial que nous achetons aujourd''hui. Cette recherche a confirmé mon envie, présente depuis longtemps, d''en faire une activité professionnelle. L''arrivée de mon premier enfant marque le moment de concrétiser ce projet : mettre ma ténacité, ma connaissance de Paris et mon plaisir de chercher au service des clients de Perle Rare.\n\nDélai de remplissage du formulaire : 00:12:17', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM formulaires_candidats WHERE FC_MessageId = '<MI3P195MB3300A3F95911A153D3D04733CC682@MI3P195MB3300.EURP195.PROD.OUTLOOK.COM>');
INSERT INTO formulaires_candidats (FC_MessageId, FC_Date, FC_From, FC_Subject, FC_Prenom, FC_Nom, FC_Tel, FC_Email, FC_Ville, FC_Linkedin, FC_Pourquoi, FC_Delai, FC_Corps, FC_Statut) SELECT '<MI3P195MB33007E24B840F54EFACFA88BCC682@MI3P195MB3300.EURP195.PROD.OUTLOOK.COM>', '2026-11-04 11:09:28', 'Georges-Louis DUQUESNE <glduquesne@hotmail.com>', 'Nouveau formulaire de recrutement via réseaux sociaux', 'Gabriel', 'LEFRANCQ', '+33623161099', 'g.lefrancq@yahoo.fr', '19, rue de la Paix - 75002 PARIS', '', 'Avec 2 expériences dans l''immobilier de prestige, j''ai découvert une vraie passion pour l''investigation immobilière et souhaite poursuivre l''aventure au service d''une équipe dédiée à la recherche de biens spécifiques pour une clientèle exigeante.', '00:04:24', 'Votre prénom ? Gabriel\n\nVotre nom ? LEFRANCQ\n\nVotre numtel ?  +33623161099\n\nVotre email ? g.lefrancq@yahoo.fr\n\nOù habitez-vous ? 19, rue de la Paix - 75002 PARIS\n\nLien linkedIn : \n\nPourquoi rejoindre PR : Avec 2 expériences dans l''immobilier de prestige, j''ai découvert une vraie passion pour l''investigation immobilière et souhaite poursuivre l''aventure au service d''une équipe dédiée à la recherche de biens spécifiques pour une clientèle exigeante.\n\nDélai de remplissage du formulaire : 00:04:24', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM formulaires_candidats WHERE FC_MessageId = '<MI3P195MB33007E24B840F54EFACFA88BCC682@MI3P195MB3300.EURP195.PROD.OUTLOOK.COM>');
